-- Actualización masiva de Códigos de Barra desde Excel
UPDATE "products" AS p
SET "specifications" = (
  SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
  FROM jsonb_array_elements(
    CASE 
      WHEN jsonb_typeof(p."specifications") = 'array' THEN p."specifications"
      ELSE '[]'::jsonb
    END
  ) AS elem
  WHERE elem->>'name' NOT IN ('Código de Barra', 'Código de Barras')
) || jsonb_build_array(jsonb_build_object('name', 'Código de Barra', 'value', v.barcode))
